sketches.source:
setcpm(132/4)

// A straight club kit, all centred
drums: stack(
  s("bd*4").shape(.2).gain(.8),
  s("[~ oh]*4").gain(.3),
  s("hh*16").hpf(8000).gain("[.25 .1]*8")
)

// The acid line: irate turns the phase between the ears, in turns per second
acid: n("0 0 7 0 3 0 10 5").scale("A:minor").sub(12)
  .s("sawtooth").lpf(perlin.range(400, 2400)).lpq(10).lpenv(2).lpdecay(.1)
  .irate("<.5 1 2 1>").legato(.5).gain(.35)

// A pad that steps from the centre of your head to all around it
// 0 degrees: centred. 90: looser. 180: diffuse, and nearly gone in mono
pad: note("<[a3,c4,e4] [f3,a3,c4]>").slow(2).s("sawtooth").unison(3).detune(.2)
  .iphase("<0 90 180 180>").lpf(1400).attack(1).release(2).room(.6).gain(.14)

// A centred sub keeps the floor
sub: note("<a1 a1 f1 f1>").s("sine").attack(.05).sustain(.8).release(.3).gain(.35)

setcpm(126/4)

// earsplit("bands") puts everything below splitfreq in one ear and above it in the other
drums: s("bd*4, ~ cp ~ cp, [~ hh]*4, hh*16?0.3").earsplit("bands").splitfreq(900).gain(.6)

// earsplit("harmonics") alternates the partials: each ear hears a thinner stab
stabs: note("<[d3,f3,a3,c4] [bb2,d3,f3,a3]>").struct("~ x ~ ~ x ~ x ~")
  .s("sawtooth").earsplit("harmonics").lpf(2400).decay(.2).sustain(0)
  .delay(.3).delaytime(3/16).delayfeedback(.35).gain(.2)

// A plain centred bass on the off-beats
bass: note("<d2 bb1>").struct("~ x ~ x ~ x ~ x")
  .s("sine").shape(.2).decay(.2).sustain(.3).release(.1).gain(.5)

setcpm(130/4)

// The kick and bass sit in front of you and never move
kick: s("bd*4").shape(.2).gain(.8)
bass: note("e1 ~ e2 ~ e1 e1 g1 ~").s("sawtooth").lpf(600).lpq(3)
  .decay(.15).sustain(.3).release(.05).gain(.45)

// Hats circle your head once every two bars, gliding between positions
hats: s("hh*16").hpf(7000).azimuth(saw.range(-180, 180).slow(2))
  .distance(2).posglide(.2).gain("[.3 .15]*8")

// A shaker turns the other way, slower and further out
shaker: s("pink*16").hpf(5000).decay(.04).sustain(0)
  .azimuth(isaw.range(-180, 180).slow(4)).distance(4).posglide(.3).gain(.06)

// Rims hop from left to right each bar, and a ride rings high overhead
rims: s("~ rim ~ ~ rim ~ ~ rim").azimuth("<-90 90>").elevation(20).gain(.3)
ride: s("[~ rd]*4").elevation(60).distance(3).gain(.18)

// A clap behind you on the backbeat
clap: s("~ cp ~ cp").azimuth(180).distance(2).room(.2).gain(.4)

setcpm(118/4)

// A soft, centred kit
drums: stack(
  s("bd*4").lpf(300).gain(.75),
  s("~ rim ~ rim").room(.4).gain(.2),
  s("[~ hh]*4").hpf(7000).gain(.2)
)

// earsh raises the right ear and lowers the left by half the value each
// 2 cents beats slowly; 30 cents widens into a chorus
chord: note("[d3,f3,a3,c4]").struct("~ x ~ ~ ~ ~ x ~")
  .s("sawtooth").earsh("<2 6 12 30>").lpf(sine.range(600, 1800).slow(8))
  .decay(.3).sustain(0).delay(.5).delaytime(3/16).delayfeedback(.55).room(.6).gain(.22)

// A deep, centred bass
bass: note("<d1 d1 bb0 c1>").struct("x ~ ~ x ~ ~ x ~")
  .s("sine").shape(.1).decay(.4).sustain(.4).release(.2).gain(.45)

// Hiss: unrelated pink noise in each ear, wide and around you
hiss: s("pink").slow(8).icorr(.15).hpf(2000).lpf(6000).gain(.03)

setcpm(126/4)

// A centred kick, clap and bass
kick: s("bd*4").shape(.2).gain(.8)
clap: s("~ cp ~ cp").room(.2).gain(.4)
bass: note("<a1 a1 f1 g1>").struct("~ x ~ x ~ x ~ x")
  .s("sawtooth").lpf(600).decay(.15).sustain(.3).gain(.42)

// The hats: the same noise in both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear the hook
ghost: s("[~ white]*4").dichotic("<[440 523 659 523] [440 523 784 659] [349 440 523 440] [392 494 587 494]>")
  .dichoticq(30).attack(.005).sustain(1).release(.05).gain(.14)

// A quiet hint: the hook on a synth, once every four bars
hint: note("<[~ a4 ~ c5 ~ e5 ~ c5] ~ ~ ~>").s("square").pw(.3)
  .decay(.15).sustain(.2).release(.1).gain(.08)

// Plain hats for the groove
hats: s("hh*16").hpf(8000).gain("[.15 .06]*8")

setcpm(112/4)

// A soft minimal kit, rolled off
drums: stack(
  s("bd*4").lpf(250).gain(.6),
  s("~ ~ rim ~ ~ ~ rim ~").room(.4).gain(.18),
  s("[~ rd]*4").gain(.12)
)

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, so a slow beat forms between them
drone: note("<f1 f1 db1 eb1>").slow(2).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.28)

// Clicks drifting slowly around the room
clicks: s("click*8?0.5").hpf(2500).azimuth(sine.range(-150, 150).slow(8))
  .distance(3).posglide(.4).seed("afterhours").gain(.12)

// A pad that barely moves
pad: note("<[f2,c3,ab3,eb4] [db2,ab2,f3,c4]>").slow(4).s("sawtooth").unison(4).detune(.3)
  .attack(4).release(6).lpf(700).room(.8).size(.9).gain(.1)
